Given an array of words words[] and a line width l, format the words such that each line has exactly l characters and is fully justified (both left and right).Pack as many words as possible into each line greedily.Distribute extra spaces as evenly as possible between words on each line.If spaces cannot be distributed evenly, the left gaps get one more space than the right gaps.The last line is left-justified with a single space between words and trailing spaces to fill the line. Return a list of strings where each string represents one formatted line.Examples:Input: words[] = ["geeksforgeeks", "is", "the", "best", "computer", "science", "portal", "for", "geeks"], l = 16Output: ["geeksforgeeks is", "the         best", "computer science", "portal for geeks"]Explanation:"geeksforgeeks is": contains 13 and 2 characters separated by 1 space."the         best": contains two words and 9 extra spaces."computer science": contains 8 and 7 characters and 1 extra space."portal for geeks":  is left-justified with single spaces.Input: words[] = ["geeks", "for", "geeks"], l = 8Output: ["geeks   ", "for     ", "geeks   "]Explanation: Each line contains a single word, so the remaining positions are filled with trailing spaces.Try It YourselfGreedy Line Packing with Space Distribution - O(n × l) Time and O(n × l) SpacePack as many words as possible into each line greedily, then distribute the remaining spaces mathematically. For a line with k words and g = k-1 gaps, compute spacePerGap = totalSpaces / g and extra = totalSpaces % g - the first extra gaps each get one more space than the rest. The last line is handled separately: single space between words, trailing spaces to fill.
            C++

    #include <vector>
#include <string>
#include <iostream>
using namespace std;

vector<string> justifyText(vector<string>& words, int l) {
    vector<string> result;
    int i = 0, n = words.size();
    while (i < n) {

        // Greedily pack words into the current line
        int lineLen = words[i].size();
        int j = i + 1;
        while (j < n && lineLen + 1 + (int)words[j].size() <= l) {
            lineLen += 1 + words[j].size();
            j++;
        }
        int numWords = j - i;
        int totalChars = 0;
        for (int k = i; k < j; k++) totalChars += words[k].size();
        int numSpaces = l - totalChars;
        string line = "";

        // Last line or single word: left justify with trailing spaces
        if (j == n || numWords == 1) {
            for (int k = i; k < j; k++) {
                if (k > i) line += " ";
                line += words[k];
            }
            line += string(l - line.size(), ' ');
        } else {

            // Distribute spaces evenly, left gaps get extra if uneven
            int gaps = numWords - 1;
            int spacePerGap = numSpaces / gaps;
            int extra = numSpaces % gaps;
            for (int k = i; k < j - 1; k++) {
                line += words[k];
                line += string(spacePerGap + (k - i < extra ? 1 : 0), ' ');
            }
            line += words[j - 1];
        }
        result.push_back(line);
        i = j;
    }
    return result;
}

int main() {
    vector<string> words = {"geeksforgeeks", "is", "the", "best", "computer",
                            "science", "portal", "for", "geeks"};
    int l = 16;
    vector<string> ans = justifyText(words, l);
    cout << "[";
    for (int i = 0; i < ans.size(); i++) {
        cout << "\"" << ans[i] << "\"";
        if (i != ans.size() - 1) cout << ", ";
    }
    cout << "]" << endl;
    return 0;
}


